return {
  json: {
    ...$json,
    threadId: String($json.thread_id ?? ''),
    groupName: String($json.group_name ?? ''),
    senderId: String($json.sender_id ?? ''),
    senderName: String($json.sender_name ?? ''),
    messageText: String($json.message_text ?? ''),
    messageTs: String($json.message_ts ?? ''),
  },
};

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const baseUrl = String($env.NINEROUTER_BASE_URL ?? 'http://127.0.0.1:20128/api/v1/api/chat').trim().replace(/\/$/, '');
const model = String($env.NINEROUTER_MODEL ?? $env.AI_MODEL ?? 'gemini/gemini-2.5-flash').trim() || 'gemini/gemini-2.5-flash';
const apiKey = String($env.NINEROUTER_API_KEY ?? $env.AI_API_KEY ?? '').trim();
const maxAttempts = Math.max(1, Number($env.NINEROUTER_MAX_ATTEMPTS ?? 3));

const prompt = [
  'Return exactly one compact JSON object. No markdown, no explanation, no code fence.',
  'Classify the Vietnamese Zalo message as attendance or other.',
  'Top-level keys in order: thread_id, group_name, sender_id, sender_name, message_text, message_ts, summary, document_type, confidence, needs_human_review, attendance_entries, notes.',
  'attendance_entries item keys: employee_name, work_date, shift, start_time, end_time, hours, overtime_hours, site, task, status, note.',
  'Use empty string for unknown text, 0 for unknown numbers, [] for arrays.',
  'Use YYYY-MM-DD for dates and HH:mm for times when known.',
  'Copy identity fields exactly from input.',
  'If the message is attendance but ambiguous, extract what you can and set needs_human_review=true.',
  '',
  `thread_id: ${$json.threadId}`,
  `group_name: ${$json.groupName}`,
  `sender_id: ${$json.senderId}`,
  `sender_name: ${$json.senderName}`,
  `message_ts: ${$json.messageTs}`,
  `message_text: ${$json.messageText}`,
].join('\n');

const parseRouterText = (response) => {
  if (typeof response === 'object' && response !== null) {
    return String(response?.message?.content ?? response?.choices?.[0]?.message?.content ?? response?.content ?? '');
  }

  const raw = String(response ?? '');
  let combined = '';
  for (const line of raw.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed === 'data: [DONE]' || trimmed === '[DONE]') continue;
    const jsonText = trimmed.startsWith('data:') ? trimmed.slice(5).trim() : trimmed;
    try {
      const chunk = JSON.parse(jsonText);
      combined += String(chunk?.message?.content ?? chunk?.choices?.[0]?.delta?.content ?? chunk?.choices?.[0]?.message?.content ?? '');
    } catch {}
  }
  return combined || raw;
};

let lastError = null;
for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (apiKey) headers.Authorization = `Bearer ${apiKey}`;

    const response = await helpers.httpRequest({
      method: 'POST',
      url: baseUrl,
      headers,
      body: {
        model,
        messages: [{ role: 'user', content: prompt }],
        temperature: 0,
        stream: false,
        max_tokens: 4096,
      },
      json: false,
    });

    const text = parseRouterText(response).trim();
    if (!text) throw new Error('9router returned no text output.');

    return {
      json: {
        ...$json,
        content: { parts: [{ text }] },
        finishReason: 'STOP',
        usageMetadata: null,
        ai_provider: '9router',
        ai_model: model,
      },
    };
  } catch (error) {
    const statusCode = Number(error?.response?.statusCode ?? error?.statusCode ?? 0);
    const message = String(error?.message ?? 'Unknown 9router error');
    lastError = `attempt ${attempt} failed (${statusCode || 'no-status'}): ${message}`;
    if (attempt >= maxAttempts) break;
    await sleep(1500 * attempt);
  }
}

throw new Error(`All 9router attempts failed. ${lastError ?? 'No detailed error available.'}`);

const normalizeText = (value) => String(value ?? '').trim();
const normalizeNumber = (value) => {
  const num = Number(value ?? 0);
  return Number.isFinite(num) ? num : 0;
};
const normalizeDate = (value) => {
  const text = normalizeText(value);
  return /^\d{4}-\d{2}-\d{2}$/.test(text) ? text : '';
};
const normalizeTime = (value) => {
  const text = normalizeText(value);
  return /^\d{2}:\d{2}$/.test(text) ? text : '';
};
const asArray = (value) => Array.isArray(value) ? value : [];
const uniq = (values) => [...new Set(values.filter(Boolean))];

const extractBalancedObject = (text) => {
  const start = text.indexOf('{');
  if (start === -1) return '';
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let i = start; i < text.length; i += 1) {
    const ch = text[i];
    if (inString) {
      if (escaped) escaped = false;
      else if (ch === '\\') escaped = true;
      else if (ch === '"') inString = false;
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === '{') depth += 1;
    else if (ch === '}') {
      depth -= 1;
      if (depth === 0) return text.slice(start, i + 1);
    }
  }
  return '';
};

const parseDateFromMessage = (messageText) => {
  const text = normalizeText(messageText);
  let match = text.match(/(\d{4})-(\d{2})-(\d{2})/);
  if (match) return `${match[1]}-${match[2]}-${match[3]}`;
  match = text.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (!match) return '';
  const day = match[1].padStart(2, '0');
  const month = match[2].padStart(2, '0');
  return `${match[3]}-${month}-${day}`;
};

const parseShiftFromMessage = (messageText) => {
  const text = normalizeText(messageText).toLowerCase();
  if (/\bb(u|ư)\s*o?i?\b[^\n]*\bs(a|á)ng\b/.test(text) || /\bca\s*s(a|á)ng\b/.test(text)) return 'ca sang';
  if (/\bb(u|ư)\s*o?i?\b[^\n]*chi(ề|e)u\b/.test(text) || /\bca\s*chi(ề|e)u\b/.test(text)) return 'ca chieu';
  if (/\bca\s*ng(a|à)y\b/.test(text)) return 'ca ngay';
  return '';
};

const parseSiteFromMessage = (messageText) => {
  const lines = normalizeText(messageText).split(/\r?\n/).map((line) => normalizeText(line)).filter(Boolean);
  if (!lines.length) return '';
  const first = lines[0]
    .replace(/^c(t|ông\s*tr(ì|i)nh)\s*/i, '')
    .replace(/^ct\s*/i, '')
    .replace(/[:.-]+$/g, '')
    .trim();
  return first;
};

const parseNamesFromMessage = (messageText) => {
  const lines = normalizeText(messageText).split(/\r?\n/).map((line) => normalizeText(line)).filter(Boolean);
  const names = [];
  for (const line of lines) {
    const numbered = line.match(/^\d+[.)]\s*(.+)$/);
    if (!numbered) continue;
    const parts = numbered[1]
      .split(/[;,]/)
      .map((part) => normalizeText(part.replace(/^[-•]+\s*/, '')))
      .filter(Boolean);
    names.push(...parts);
  }
  return uniq(names);
};

const buildFallbackData = (messageText) => {
  const workDate = parseDateFromMessage(messageText);
  const shift = parseShiftFromMessage(messageText);
  const site = parseSiteFromMessage(messageText);
  const names = parseNamesFromMessage(messageText);
  const attendanceEntries = names.map((employeeName) => ({
    employee_name: employeeName,
    work_date: workDate,
    shift,
    start_time: '',
    end_time: '',
    hours: 0,
    overtime_hours: 0,
    site,
    task: '',
    status: '',
    note: '',
  }));
  return {
    summary: attendanceEntries.length ? `Chấm công ${attendanceEntries.length} người${site ? ` tại ${site}` : ''}.` : '',
    document_type: attendanceEntries.length ? 'attendance' : 'other',
    confidence: attendanceEntries.length ? 0.55 : 0,
    needs_human_review: true,
    attendance_entries: attendanceEntries,
    notes: attendanceEntries.length ? ['AI trả JSON bị cắt, đã fallback từ nội dung tin nhắn gốc.'] : [],
  };
};

const finishReason = normalizeText($json?.finishReason);
const parts = $json?.content?.parts ?? [];
const textPart = parts.find((part) => typeof part?.text === 'string')?.text ?? '';
const rawOutput = textPart
  .replace(/^```json\s*/i, '')
  .replace(/^```/i, '')
  .replace(/```$/i, '')
  .trim();

let clean = extractBalancedObject(rawOutput) || rawOutput;
let data;
let usedFallback = false;

try {
  data = JSON.parse(clean);
} catch (error) {
  const fallback = buildFallbackData($json.messageText ?? $input.item.json.message_text ?? '');
  if (!fallback.attendance_entries.length) {
    throw new Error(`Gemini did not return valid JSON. Finish reason: ${finishReason}. Raw output: ${rawOutput}`);
  }
  data = fallback;
  clean = JSON.stringify(fallback);
  usedFallback = true;
}

const attendanceEntries = asArray(data.attendance_entries).map((entry) => ({
  employee_name: normalizeText(entry?.employee_name),
  work_date: normalizeDate(entry?.work_date) || parseDateFromMessage($json.messageText ?? ''),
  shift: normalizeText(entry?.shift) || parseShiftFromMessage($json.messageText ?? ''),
  start_time: normalizeTime(entry?.start_time),
  end_time: normalizeTime(entry?.end_time),
  hours: normalizeNumber(entry?.hours),
  overtime_hours: normalizeNumber(entry?.overtime_hours),
  site: normalizeText(entry?.site) || parseSiteFromMessage($json.messageText ?? ''),
  task: normalizeText(entry?.task),
  status: normalizeText(entry?.status),
  note: normalizeText(entry?.note),
})).filter((entry) => entry.employee_name || entry.work_date || entry.site || entry.task || entry.hours || entry.overtime_hours);

const notes = uniq([
  ...asArray(data.notes).map((note) => normalizeText(note)),
  ...(usedFallback ? ['Đã dùng fallback parser từ tin nhắn gốc.'] : []),
  ...(finishReason === 'MAX_TOKENS' ? ['Gemini bị giới hạn token ở lần chạy này.'] : []),
]).filter(Boolean);

const documentType = normalizeText(data.document_type) || (attendanceEntries.length ? 'attendance' : 'other');
let queueStatus = 'ignored';
if (documentType === 'attendance' && attendanceEntries.length > 0) queueStatus = 'done';
else if (documentType === 'attendance' || Boolean(data.needs_human_review) || usedFallback) queueStatus = 'needs_review';

const summary = normalizeText(data.summary) || (attendanceEntries.length ? `Chấm công ${attendanceEntries.length} người${attendanceEntries[0]?.site ? ` tại ${attendanceEntries[0].site}` : ''}.` : '');

return {
  json: {
    ...$input.item.json,
    finish_reason: finishReason,
    summary,
    document_type: documentType,
    confidence: usedFallback ? Math.min(normalizeNumber(data.confidence || 0.55), 0.7) : normalizeNumber(data.confidence),
    needs_human_review: usedFallback ? true : Boolean(data.needs_human_review),
    attendance_entries: attendanceEntries,
    notes,
    status: queueStatus,
    processed_at: new Date().toISOString(),
    attendance_json: JSON.stringify(attendanceEntries),
    appscript_action: { mode: 'route_attendance', targets: ['ChamCong'] },
    raw_ai_json: clean,
  },
};

const pickQueueFields = (input, overrides = {}) => ({
  id: input.id,
  queue_key: String(input.queue_key ?? ''),
  thread_id: String(input.thread_id ?? ''),
  group_name: String(input.group_name ?? ''),
  sender_id: String(input.sender_id ?? ''),
  sender_name: String(input.sender_name ?? ''),
  message_text: String(input.message_text ?? ''),
  message_ts: String(input.message_ts ?? ''),
  raw_message_json: String(input.raw_message_json ?? ''),
  status: String(input.status ?? 'pending'),
  retry_count: Number(input.retry_count ?? 0),
  last_error: String(input.last_error ?? ''),
  processed_at: input.processed_at ?? null,
  summary: String(input.summary ?? ''),
  attendance_json: String(input.attendance_json ?? ''),
  needs_human_review: Boolean(input.needs_human_review),
  confidence: Number(input.confidence ?? 0),
  appscript_response: String(input.appscript_response ?? ''),
  ...overrides,
});

if ($json.document_type !== 'attendance' || !Array.isArray($json.attendance_entries) || $json.attendance_entries.length === 0) {
  return { json: pickQueueFields($json, { appscript_response: JSON.stringify({ skipped: true, reason: 'non-attendance-or-empty' }) }) };
}

const url = 'https://script.google.com/macros/s/AKfycbyzC-qw38puhlm5btycJs6ohYXArbRWBF7j70o0zU4MeHCWaoKjXM4BN4XXZXveHsgD/exec';
const response = await helpers.httpRequest({ method: 'POST', url, headers: { 'Content-Type': 'application/json' }, body: $json, json: false });
const responseText = typeof response === 'string' ? response : JSON.stringify(response);
const responseLower = responseText.toLowerCase();
if (responseLower.includes('<!doctype html>') || responseLower.includes('không tìm thấy hàm tập lệnh: dopost') || responseLower.includes('khong tim thay ham tap lenh: dopost')) throw new Error(`Apps Script deployment is invalid or missing doPost. Response: ${responseText}`);
let parsed;
try { parsed = JSON.parse(responseText); } catch (error) { throw new Error(`Apps Script did not return valid JSON. Response: ${responseText}`); }
if (!parsed?.ok) throw new Error(`Apps Script returned ok=false. Response: ${responseText}`);
return { json: pickQueueFields($json, { appscript_response: responseText }) };
